use crate::domains::rust_perf::PerfRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<PerfRule> {
    vec![
        // ── complexity (fixpoint convergence): a worklist fixpoint's
        // iteration count is TRAVERSAL-ORDER dependent — re-dirtied nodes
        // must be re-reached in DATAFLOW order (min-rank), never FIFO
        // push-back ─────────────────────────────────────────────────────
        // Source: rust-lang/rust #160193 (the merged framework/mod.rs
        // comment block) + the nnethercote 2026-09-30 perf blog.
        PerfRule {
            rule_id: "dataflow-fixpoint-convergence-traversal-order".to_string(),
            name: "a worklist fixpoint over a CFG converges in an order-dependent number of iterations — seed the worklist in dataflow order (reverse postorder for forward analyses) AND re-process re-dirtied nodes in dataflow order too: a min-rank pointer that rewinds to the earliest re-dirtied node on a back edge, instead of pushing re-dirtied nodes onto the BACK of a FIFO queue where later blocks get processed on soon-to-be-stale inputs; loop-free regions then converge in a single pass, and pathological back-edge-heavy CFGs stop re-visiting the whole loop body per dirtying".to_string(),
            category: "complexity".to_string(),
            buggy_code: "// NAIVE: a dataflow fixpoint over a FIFO worklist. The seed order\n// (reverse postorder) is right, but re-dirtied blocks are pushed to\n// the BACK: on a back edge B -> A, every block after A already in the\n// queue is processed on inputs that are about to change again — the\n// loop body re-visits block by block on stale states until the queue\n// drains, and a pathological 18k-block function pays millions of\n// effect applications to converge.\nuse std::collections::VecDeque;\n\npub fn fixpoint_fifo(\n    order: &[usize],      // reverse postorder (the seed order)\n    effects: &[fn(u64) -> Option<u64>], // per-block effect on the state\n    succs: &[Vec<usize>], // the CFG's successor lists\n) -> u64 {\n    let n = order.len();\n    let mut state = vec![0u64; n];\n    let mut in_queue = vec![true; n];\n    let mut queue: VecDeque<usize> = order.to_vec().into();\n    let mut applications = 0u64;\n    while let Some(b) = queue.pop_front() {\n        in_queue[b] = false;\n        applications += 1;\n        let before = state[b];\n        for f in &effects[b..b + 1] {\n            if let Some(v) = f(state[b]) {\n                state[b] = v;\n            }\n        }\n        let _ = before;\n        for &s in &succs[b] {\n            if state[s] < state[b] {\n                state[s] = state[b];\n                if !in_queue[s] {\n                    in_queue[s] = true;\n                    queue.push_back(s); // FIFO push-back: s lands behind\n                                         // every block already waiting,\n                                         // stale-processing them all\n                }\n            }\n        }\n    }\n    applications\n}".to_string(),
            fixed_code: "// OPT: a MIN-RANK worklist. Give every block a rank = its position\n// in dataflow order (reverse postorder for forward analyses — for\n// every non-back edge A -> B, rank(A) < rank(B)); keep a dirty bitset\n// and a cursor `curr` that always points at the MINIMUM-rank dirty\n// block. Processing a block may re-dirty an earlier rank through a\n// back edge — the cursor rewinds to that lower-or-equal rank\n// IMMEDIATELY, so no later block is ever processed on soon-to-be-\n// stale inputs. Advancing is a bitset scan from the cursor\n// (`first_set_at_or_after`), and loop-free code converges in one pass.\nfn fixpoint_min_rank(\n    order: &[usize],    // reverse postorder: index = the block's rank\n    effects: &[fn(u64) -> Option<u64>], // per-block effect on the state\n    succs: &[Vec<usize>], // the CFG's successor lists\n) -> u64 {\n    let n = order.len();\n    let mut state = vec![0u64; n];\n    // rank-of-block: position of each block in dataflow order.\n    let mut rank_of = vec![usize::MAX; n];\n    for (r, &b) in order.iter().enumerate() {\n        rank_of[b] = r;\n    }\n    // All reachable blocks start dirty (the real implementation fills\n    // a DenseBitSet over ranks; a sorted-count bitset stands in here).\n    let mut dirty = vec![true; n];\n    let dirty_count = n;\n    let mut applications = 0u64;\n    let mut curr = 0usize; // invariant: curr is the minimum-rank dirty block\n    while dirty_count > 0 {\n        debug_assert!(dirty[curr]);\n        dirty[curr] = false; // the invariant is briefly broken while the\n                             // block's effects run\n        applications += 1;\n        for f in &effects[curr..curr + 1] {\n            if let Some(v) = f(state[curr]) {\n                state[curr] = v;\n            }\n        }\n        for &s in &succs[curr] {\n            let r = rank_of[s];\n            if state[s] < state[curr] {\n                state[s] = state[curr];\n                if !dirty[r] {\n                    dirty[r] = true;\n                }\n                if r <= curr {\n                    curr = r; // back edge rewound us: return to the\n                              // earlier block immediately\n                }\n            }\n        }\n        match (curr..n).find(|&r| dirty[r]) {\n            Some(r) => curr = r, // advance to the next dirty rank\n            None => break,       // no dirty blocks: the fixpoint is reached\n        }\n    }\n    applications\n}".to_string(),
            context_notes: Some("Grade B — NotBenchable decision-content (the win is a fixpoint's ITERATION COUNT on the workload's own CFG — a standalone microbench of a worklist measures the wrong thing; the Batch-182/186 corpus-only precedent; lands for decision content + honest annotations, no proposer files; suggestion-only in spirit — the traversal is an admission shape for any fixpoint the healed code contains, never a mechanical rewrite). SOURCE (rust-lang/rust #160193 \"Improve CFG traversal\", merge commit cb9d1b0640549f1b041aae430dc413ce93f8c204, merged 2026-08-01T04:45:44Z, milestone 1.99.0, r=cjgillot; compiler/rustc_mir_dataflow/src/framework/mod.rs, verbatim): THE RANK — 'Every reachable basic block has a *rank*: its position within `rpo`. Rank order is dataflow order: for every edge A -> B that is not a back edge, rank(A) < rank(B).' (:297-299); THE ALGORITHM — 'The CFG traversal uses a \"min-rank\" algorithm. First, all reachable basic blocks are marked as dirty. The loop-head invariant is that `curr_rank` always points to the minimum-rank dirty block in `rpo`. Before processing that block we mark it as clean. If the processing dirties a block with a rank lower than or equal to `curr_rank` (via a back edge, which could be an edge-to-self) then `curr_rank` is set to that lower-or-equal rank. After the block is processed, if `curr_rank` doesn't point to a dirty block it is moved to the next dirty block, and we iterate again.' (:301-308); THE GUARANTEE — 'This algorithm ensures each basic block is processed only after all its dirty predecessors (ignoring back edges). When a back edge dirties an earlier block we return to that earlier block immediately, which avoids processing later blocks with possibly soon-to-be-stale information. Loop-free code is processed in a single pass.' (:309-312); the advance is a bitset scan — 'match dirty.first_set_at_or_after(curr_rank)' (:367) with 'Some(rank) => curr_rank = rank, // broken invariant re-established' / 'None => break, // no more dirty blocks; finish' (:368-369); the rewind — 'dirty.insert(target_rank);' + 'curr_rank = curr_rank.min(target_rank);' (:361-362); the rank assignment — 'let rank = if Self::Direction::IS_FORWARD { i } else { last - i };' (:331, the backward analyses fake a postorder by flipping the rank mapping, :316-317). BLOG FIGURES (nnethercote, 'How to speed up the Rust compiler in September 2026', 2026-09-30, verbatim): 'The old algorithm required 1.5 million calls to apply_effects_in_block to reach a fixpoint for the EverInitializedPlaces analysis used by the borrow checker; the new algorithm requires 90,000. This gave an enormous ~30% wall-time reduction for a check build of this crate.' — the crate is cranelift-codegen, the function 'over 18,000 basic blocks' (blog). ⛔ DRIFT CORRECTED vs the 10-02 staging row: the '17% reduction in instruction counts' figure belongs to #160033 (EverInitializedPlaces projection-data pruning; match-stress benchmark) — a DIFFERENT PR; this rule must never cite 17%. The 10-02 row's 1,508,264/89,809 precise pair was NOT re-found in the PR issue/comments this pass — NOT carried; the blog's rounded figures + the merged implementation comment carry the rule. MECHANISM PRECISION (the 10-02 correction, held): the old FIFO worklist WAS seeded in good order (reverse postorder) — the defect is the RE-DIRTY policy (push-back), so the rule is 're-process in dataflow order (min-rank)', not 'seed in RPO' (seeding alone was already the old behavior). REGIME: worklist fixpoints over CFG-shaped dependency graphs (dataflow analyses, liveness, type/constant propagation, any iterate-to-fixpoint pass) where a back edge re-dirties an earlier node. ANTI-REGIME: order-insensitive fixpoints (convergence count independent of order); DAG-shaped graphs (no back edges — one pass in any topological order); graphs too small for the ordering to matter ('for most code the new algorithm makes no difference' — blog). KINSHIP (do not double-count): the rust_perf dispatch family reorders WORK SELECTION for cache/latency (selector-lattice-beam-over-greedy-walk, entries_12, B198 — widens a selection walk, not a fixpoint); this is a CONVERGENCE-ORDER rule — the first of its axis. NOVEL: grep fixpoint/worklist/traversal-order/dataflow over the rust_perf + kernel_opt corpora returns zero rules (the hits are unrelated prose — entries_06's unknown-amount parallelism is a different family). Cite: rust-lang/rust @ cb9d1b06 — compiler/rustc_mir_dataflow/src/framework/mod.rs:297-312+316-317+331+361-362+367-369; nnethercote.github.io /2026/09/30/ (the blog paragraph, verbatim); PR #160193 (merged 2026-08-01, milestone 1.99.0, r=cjgillot, head 4aadc68a8a49); Batch 202 / Plan 201.".to_string()),
            // Not benchable: the win is iteration count on the workload's
            // own CFG — no standalone microbench axis.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
